TRV_st.name='TRV'; 
TRV_st.lat=8.58;
TRV_st.lon=77.03;
TRV_st.alt=0000;
TRV_st.env='Con';
TRV_st.footp='RB';
%%
% data imported via the import tool from matlab
 TRV_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\TRV_2016-2026_Hour.csv", [2, Inf]);
TRV_rd_h.Properties.DimensionNames{1}='Time';
TRV_rd_h.Properties.VariableNames{2}='Ba1_A';
TRV_rd_h.Properties.VariableNames{3}='Ba2_A';
TRV_rd_h.Properties.VariableNames{4}='Ba3_A';
TRV_rd_h.Properties.VariableNames{5}='Ba4_A';
TRV_rd_h.Properties.VariableNames{6}='Ba5_A';
TRV_rd_h.Properties.VariableNames{7}='Ba6_A';
TRV_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(TRV_rd_h);
%%
TRV_rd=retime(TRV_rd_h,'daily',@nanmedian);
%%
datevec(TRV_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(TRV_rd.Time(end)) % end in 2022 June %[output:0c280ed0]
plotFigControl(TRV_rd,TRV_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
TRV_cal=compute_exp_D(TRV_rd,names_abs,lambdaAE7); %[output:7c63b252]
plotFigControl_cal(TRV_cal,TRV_st.name); %[output:82c59cd2] %[output:8bd43c8b] %[output:4dfd1420]
%%
%HOMOGENEITY

break_TRV_abs_BP=change_point_analysis_Def(TRV_rd,names_abs,0.05,'TRV','Absorption'); %[output:6b7ee9f8] %[output:5a393386] %[output:85ed12d1] %[output:4eb1a59d] %[output:9f80f676] %[output:25df2fe7]
T_TRV_abs_BP=make_table_breakpoints_def(break_TRV_abs_BP); %[output:9a0fc507]

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:852708f3]
break_TRV_expA_BP=change_point_analysis_Def(TRV_cal,names_expA,0.05,'TRV','Absorption exponent'); %[output:776eecee] %[output:91fe9fa3] %[output:9f6c0857] %[output:7c52163f]
T_TRV_expA_BP=make_table_breakpoints_def(break_TRV_expA_BP); %[output:51d33ff8] %[output:43f732e3] %[output:542b5d5c]




